proof fn always_double_equality<T>(p: TempPred<T>)
    ensures always(always(p)) == always(p),
{
    let a1: TempPred<T> = always(always(p));
    let a2: TempPred<T> = always(p);

    // Show both entailments so we can use temp_pred_equality.
    assert(a1.entails(a2)) by {
        reveal(TempPred::entails);
        reveal(TempPred::implies);
        reveal(valid);
        reveal(always);

        forall |ex: Execution<T>| {
            // Prove: a1.satisfied_by(ex) ==> a2.satisfied_by(ex)
            if a1.satisfied_by(ex) {
                // Need: forall k, p.satisfied_by(ex.suffix(k))
                forall |k: nat| {
                    // Instantiate the outer 'always' at offset 0.
                    have h0: always(p).satisfied_by(ex.suffix(0)) = {
                        // a1.satisfied_by(ex) unfolds to: forall i, always(p).satisfied_by(ex.suffix(i))
                        // so evaluating at i = 0 gives the needed fact.
                        let hforall = a1.satisfied_by(ex);
                        assert(hforall);
                        hforall(0)
                    };

                    // Instantiate the inner 'always' at offset k.
                    have h1: p.satisfied_by(ex.suffix(0).suffix(k)) = {
                        let hinner = h0;
                        assert(hinner);
                        hinner(k)
                    };

                    // Now use suffix composition: ex.suffix(0).suffix(k) == ex.suffix(k)
