use vstd::prelude::*;

fn main() {}

verus!{

// File: defs.rs
pub struct Execution<T> {
    pub nat_to_state: spec_fn(nat) -> T,
}

impl<T> Execution<T> {

    pub open spec fn suffix(self, pos: nat) -> Self {
        Execution {
            nat_to_state: |i: nat| (self.nat_to_state)(i + pos),
        }
    }

}


#[verifier(reject_recursive_types(T))]
pub struct TempPred<T> {
    pub pred: spec_fn(Execution<T>) -> bool,
}

impl<T> TempPred<T> {

    pub open spec fn new(pred: spec_fn(Execution<T>) -> bool) -> Self {
        TempPred {
            pred: pred,
        }
    }

    pub open spec fn satisfied_by(self, execution: Execution<T>) -> bool {
        (self.pred)(execution)
    }

    pub open spec fn implies(self, other: Self) -> Self {
        TempPred::new(|ex: Execution<T>| self.satisfied_by(ex) ==> other.satisfied_by(ex))
    }

    pub open spec fn entails(self, other: Self) -> bool {
        valid(self.implies(other))
    }

}


pub open spec fn always<T>(temp_pred: TempPred<T>) -> TempPred<T> {
    TempPred::new(|ex: Execution<T>| forall |i: nat| #[trigger] temp_pred.satisfied_by(ex.suffix(i)))
}

pub open spec fn valid<T>(temp_pred: TempPred<T>) -> bool {
    forall |ex: Execution<T>| temp_pred.satisfied_by(ex)
}


// File: rules.rs
	#[verifier::external_body]
pub proof fn execution_equality<T>(ex1: Execution<T>, ex2: Execution<T>)
    requires forall |i: nat| #[trigger] (ex1.nat_to_state)(i) == (ex2.nat_to_state)(i),
    ensures ex1 == ex2,
	{
		unimplemented!()
	}

	#[verifier::external_body]
pub proof fn temp_pred_equality<T>(p: TempPred<T>, q: TempPred<T>)
    requires
        p.entails(q),
        q.entails(p),
    ensures p == q,
	{
		unimplemented!()
	}

proof fn always_double_equality<T>(p: TempPred<T>)
    ensures always(always(p)) == always(p),
{
    let a1: TempPred<T> = always(always(p));
    let a2: TempPred<T> = always(p);

    // Prove both entailments required by temp_pred_equality.
    assert(a1.entails(a2)) by {
        reveal(TempPred::entails);
        reveal(TempPred::implies);
        reveal(valid);

        // Goal is: forall ex, a1.satisfied_by(ex) ==> a2.satisfied_by(ex)
        forall |ex: Execution<T>| {
            if a1.satisfied_by(ex) {
                // Unfold a2 = always(p).
                reveal(always);
                // Need: forall k, p.satisfied_by(ex.suffix(k))
                forall |k: nat| {
                    // From a1.satisfied_by(ex), get always(p).satisfied_by(ex.suffix(0))
                    assert(always(p).satisfied_by(ex.suffix(0)));
                    // Then get p.satisfied_by(ex.suffix(0).suffix(k))
                    assert(p.satisfied_by(ex.suffix(0).suffix(k)));

                    // Now rewrite ex.suffix(0).suffix(k) to ex.suffix(k)
                    let ex1: Execution<T> = ex.suffix(0).suffix(k);
                    let ex2: Execution<T> = ex.suffix(k);
                    reveal(Execution::suffix);
                    assert(forall |i: nat| #[trigger] (ex1.nat_to_state)(i) == (ex2.nat_to_state)(i));
                    execution_equality(ex1, ex2);
                    assert(p.satisfied_by(ex2));
                    p.satisfied_by(ex2)
                }
            } else {
                true
            }
        };
    };

    assert(a2.entails(a1)) by {
        reveal(TempPred::entails);
        reveal(TempPred::implies);
        reveal(valid);

        // Goal is: forall ex, a2.satisfied_by(ex) ==> a1.satisfied_by(ex)
        forall |ex: Execution<T>| {
            if a2.satisfied_by(ex) {
                reveal(always);

                // Need: a1.satisfied_by(ex) = forall i, always(p).satisfied_by(ex.suffix(i))
                forall |i: nat| {
                    // Show always(p).satisfied_by(ex.suffix(i))
                    reveal(always);
                    forall |k: nat| {
                        // a2 gives: p.satisfied_by(ex.suffix(i+k))
                        let m: nat = i + k;
                        assert(p.satisfied_by(ex.suffix(m)));

                        // Rewrite ex.suffix(i).suffix(k) to ex.suffix(i+k)
                        let ex1: Execution<T> = ex.suffix(i).suffix(k);
                        let ex2: Execution<T> = ex.suffix(m);
                        reveal(Execution::suffix);
                        assert(forall |j: nat| #[trigger] (ex1.nat_to_state)(j) == (ex2.nat_to_state)(j));
                        execution_equality(ex1, ex2);

                        assert(p.satisfied_by(ex1));
                        p.satisfied_by(ex1)
                    }
                }
            } else {
                true
            }
        };
    };

    temp_pred_equality(a1, a2);
}


}

