proof fn always_double_equality<T>(p: TempPred<T>)
    ensures always(always(p)) == always(p),
{
    let a1: TempPred<T> = always(always(p));
    let a2: TempPred<T> = always(p);

    // Unfold the definitions and show equality of the underlying predicates.
    // For any execution `ex`, both sides reduce to
    //   forall i, j: nat. p.satisfied_by(ex.suffix(i+j))
    // which is equivalent to
    //   forall k: nat. p.satisfied_by(ex.suffix(k)).
    assert(a1.pred == a2.pred) by {
        reveal(always);
        forall |ex: Execution<T>| {
            // a1.pred(ex)
            assert(a1.satisfied_by(ex) == a2.satisfied_by(ex));
        }
    };

    assert(a1 == a2);
}

